    const row=project=>{const metrics=project.metrics||{},count=(project.nodes||[]).length,stage=count?metrics.current_stage||project.nodes[0]?.stage:'',upcoming=metrics.upcoming?.[0]?.date,overdue=Number(metrics.overdue_count)||0,status=count?`${esc(stage||'未开始')}${overdue?` · <b class="tl-red">逾期 ${overdue}</b>`:''}${upcoming?` · 临近 ${esc(upcoming.slice(5).replace('-','/'))}`:''}`:'未开始 · 待录入首个节点';return `<article class="tl-prow" data-project-choice="${project.project_id}" data-order-project="${project.project_id}"><button type="button" class="tl-order-grip" draggable="true" aria-label="拖拽调整我的顺序" tabindex="-1">⋮⋮</button><button type="button" class="tl-prow-main" data-timeline-open="single" data-project-id="${project.project_id}"><i class="tl-prow-dot ${count?stageClass(stage):'is-empty'}"></i><strong>${esc(project.name)}</strong><span class="tl-prow-meta">${status}</span>${overdue?`<span class="tl-risk-chip">逾期 ${overdue}</span>`:''}<span class="tl-prow-go" aria-hidden="true">›</span></button><span class="tl-prow-actions"><button type="button" data-timeline-open="editor" data-project-id="${project.project_id}">编辑</button>${admin?`<button type="button" class="timeline-delete" data-timeline-delete="${project.project_id}" data-project-version="${project.version}">删除</button>`:''}</span></article>`};
    const strip=member=>{const owned=projects.filter(project=>ownedBy(project,member)),isMe=Boolean(currentUser&&member.id===currentUser.id),pills=owned.map((project,index)=>{const metrics=project.metrics||{},overdue=Number(metrics.overdue_count)||0,upcoming=metrics.upcoming?.[0]?.date,locked=!admin&&!ownedBy(project,currentUser);return `<button type="button" class="tl-pill ${stageClass(metrics.current_stage)}" data-timeline-member-open="${project.project_id}"${index>=10?' data-member-extra hidden':''}><i class="dot"></i><b>${esc(project.name)}</b><small>${overdue?`逾期 ${overdue}`:esc(metrics.current_stage||'未开始')}${upcoming?` · 临近 ${esc(upcoming.slice(5).replace('-','/'))}`:''}</small>${locked?'<span class="tl-lock">🔒 只读</span>':''}</button>`}).join(''),more=owned.length>10?`<button type="button" class="tl-member-more" data-timeline-member-toggle="${esc(member.id)}" aria-expanded="false">显示全部（剩余 ${owned.length-10} 个）</button>`:'';return `<div class="tl-mrow"><div class="tl-member-head"><span class="tl-mavatar" aria-hidden="true">${esc(String(member.name||'?').slice(0,1))}</span><span><b>${esc(member.name||'')}${isMe?'（我）':''}</b><small>${isMe&&admin?'admin':'member'} · ${owned.length} 个项目</small></span></div><span class="tl-mpills">${owned.length?`${pills}${more}`:'<span class="tl-mnone">暂无负责项目</span>'}</span></div>`};
