    const projectMode=['single','editor'].includes(mode),homeMode=['home','tags','archived'].includes(mode),toolbar=projectMode||homeMode?'':`<div class="timeline-toolbar"><nav aria-label="项目时间管理页面"><button type="button" data-timeline-mode-target="home">项目列表</button><button type="button" data-timeline-mode-target="editor" ${selected?'':'disabled'}>时间表编辑器</button><button type="button" data-timeline-mode-target="single" ${selected?'':'disabled'}>单项目仪表盘</button><button type="button" data-timeline-mode-target="all">全项目仪表盘</button></nav>${write?'<form data-timeline-create><label>项目名称 <input name="name" maxlength="200" required></label><button type="submit">新建项目</button></form>':''}</div>`,transferActive=Boolean(transfer.busy||transfer.filename||transfer.preview||transfer.error||transfer.committed||transfer.exportReady);
